//! QR Model 2 encoder — byte mode, EC level M, versions 1-10 (ADR-011: `companion
//! pair` prints a terminal QR carrying the pairing payload). Zero dependencies.
//!
//! Verified against byte-mode reference matrices generated by the trusted
//! `qrcode` library (frozen in `qr_ref_data.rs`), for a small 1-block code, an
//! alignment+2-block code, and a multi-block+version-info code at two masks.

/// A rendered QR: `size × size` modules, row-major, `true` = dark.
pub struct Qr {
    pub size: usize,
    pub modules: Vec<bool>,
}

impl Qr {
    pub fn get(&self, row: usize, col: usize) -> bool {
        self.modules[row * self.size + col]
    }
}

// Total codewords (data + ECC) per version; index 0 unused.
const TOTAL_CODEWORDS: [usize; 16] = [
    0, 26, 44, 70, 100, 134, 172, 196, 242, 292, 346, 404, 466, 532, 581, 655,
];

/// Level-M block layout: EC codewords per block, plus `(block_count, data_codewords)`
/// groups. Index 0 unused.
struct MLayout {
    ec_per_block: u8,
    groups: &'static [(u8, u8)],
}
const LEVEL_M: [MLayout; 16] = [
    MLayout {
        ec_per_block: 0,
        groups: &[],
    },
    MLayout {
        ec_per_block: 10,
        groups: &[(1, 16)],
    },
    MLayout {
        ec_per_block: 16,
        groups: &[(1, 28)],
    },
    MLayout {
        ec_per_block: 26,
        groups: &[(1, 44)],
    },
    MLayout {
        ec_per_block: 18,
        groups: &[(2, 32)],
    },
    MLayout {
        ec_per_block: 24,
        groups: &[(2, 43)],
    },
    MLayout {
        ec_per_block: 16,
        groups: &[(4, 27)],
    },
    MLayout {
        ec_per_block: 18,
        groups: &[(4, 31)],
    },
    MLayout {
        ec_per_block: 22,
        groups: &[(2, 38), (2, 39)],
    },
    MLayout {
        ec_per_block: 22,
        groups: &[(3, 36), (2, 37)],
    },
    MLayout {
        ec_per_block: 26,
        groups: &[(4, 43), (1, 44)],
    },
    // v11-15 (ISO/IEC 18004 Table 9): a pairing QR with LAN + tunnel endpoints
    // is ~250 bytes, past v10's 213
    MLayout {
        ec_per_block: 30,
        groups: &[(1, 50), (4, 51)],
    },
    MLayout {
        ec_per_block: 22,
        groups: &[(6, 36), (2, 37)],
    },
    MLayout {
        ec_per_block: 22,
        groups: &[(8, 37), (1, 38)],
    },
    MLayout {
        ec_per_block: 24,
        groups: &[(4, 40), (5, 41)],
    },
    MLayout {
        ec_per_block: 24,
        groups: &[(5, 41), (5, 42)],
    },
];

/// Highest version this encoder emits (v15-M: 412 bytes).
pub const MAX_VERSION: u8 = 15;

/// Alignment-pattern centre coordinates per version; index 0 unused.
const ALIGN: [&[u8]; 16] = [
    &[],
    &[],
    &[6, 18],
    &[6, 22],
    &[6, 26],
    &[6, 30],
    &[6, 34],
    &[6, 22, 38],
    &[6, 24, 42],
    &[6, 26, 46],
    &[6, 28, 50],
    &[6, 30, 54],
    &[6, 32, 58],
    &[6, 34, 62],
    &[6, 26, 46, 66],
    &[6, 26, 48, 70],
];

/// Maximum byte-mode payload for level M at `version` (v1-9 use an 8-bit length
/// field, v10 uses 16-bit).
fn byte_capacity(version: u8) -> usize {
    let data_codewords: usize = LEVEL_M[version as usize]
        .groups
        .iter()
        .map(|&(n, d)| n as usize * d as usize)
        .sum();
    let count_bits = if version >= 10 { 16 } else { 8 };
    (data_codewords * 8 - 4 - count_bits) / 8
}

/// Encode `data` in byte mode at EC level M, auto-picking the smallest version.
pub fn encode(data: &[u8]) -> Result<Qr, String> {
    for version in 1..=MAX_VERSION {
        if data.len() <= byte_capacity(version) {
            return encode_forced(data, version, None);
        }
    }
    Err(format!(
        "payload of {} bytes exceeds QR v{MAX_VERSION}-M capacity ({} bytes)",
        data.len(),
        byte_capacity(MAX_VERSION)
    ))
}

/// Encode at an exact version; `mask` forces a mask (tests) or `None` to pick
/// the lowest-penalty mask.
pub fn encode_forced(data: &[u8], version: u8, mask: Option<u8>) -> Result<Qr, String> {
    assert!((1..=MAX_VERSION).contains(&version), "version out of range");
    if data.len() > byte_capacity(version) {
        return Err(format!(
            "payload of {} bytes exceeds QR v{version}-M capacity ({} bytes)",
            data.len(),
            byte_capacity(version)
        ));
    }
    let codewords = build_codewords_full(data, version);

    let chosen = match mask {
        Some(m) => m,
        None => pick_mask(version, &codewords),
    };
    Ok(build_matrix(version, chosen, &codewords))
}

// ---- GF(256) arithmetic for Reed-Solomon (QR primitive polynomial 0x11d) ----

struct Gf {
    exp: [u8; 512],
    log: [u8; 256],
}

fn gf_tables() -> Gf {
    let mut exp = [0u8; 512];
    let mut log = [0u8; 256];
    let mut x: u16 = 1;
    for (i, slot) in exp[..255].iter_mut().enumerate() {
        *slot = x as u8;
        log[x as usize] = i as u8;
        x <<= 1;
        if x & 0x100 != 0 {
            x ^= 0x11d;
        }
    }
    for i in 255..512 {
        exp[i] = exp[i - 255];
    }
    Gf { exp, log }
}

impl Gf {
    fn mul(&self, a: u8, b: u8) -> u8 {
        if a == 0 || b == 0 {
            0
        } else {
            self.exp[self.log[a as usize] as usize + self.log[b as usize] as usize]
        }
    }

    /// Generator polynomial for `ec_len` EC codewords (roots α^0..α^(ec_len-1)),
    /// coefficients highest-degree-first excluding the leading 1.
    fn generator(&self, ec_len: usize) -> Vec<u8> {
        let mut g: Vec<u8> = vec![1];
        for i in 0..ec_len {
            let root = self.exp[i];
            let mut next = vec![0u8; g.len() + 1];
            for (a, &coef) in g.iter().enumerate() {
                next[a] ^= coef; // × x
                next[a + 1] ^= self.mul(coef, root); // × α^i
            }
            g = next;
        }
        g[1..].to_vec()
    }

    /// Reed-Solomon remainder (the EC codewords) for `data`.
    fn ecc(&self, data: &[u8], genpoly: &[u8]) -> Vec<u8> {
        let mut rem = vec![0u8; genpoly.len()];
        for &d in data {
            let factor = d ^ rem[0];
            rem.remove(0);
            rem.push(0);
            for (i, &g) in genpoly.iter().enumerate() {
                rem[i] ^= self.mul(g, factor);
            }
        }
        rem
    }
}

/// Build the raw data bit stream (mode + length + payload + terminator + padding)
/// and pack into data codewords sized exactly for `version`.
fn data_codewords(data: &[u8], version: u8) -> Vec<u8> {
    let data_len: usize = LEVEL_M[version as usize]
        .groups
        .iter()
        .map(|&(n, d)| n as usize * d as usize)
        .sum();
    let mut bits: Vec<bool> = Vec::with_capacity(data_len * 8);
    // mode indicator: byte = 0100
    for b in [false, true, false, false] {
        bits.push(b);
    }
    // character count (8 bits v1-9, 16 bits v10)
    let count_bits = if version >= 10 { 16 } else { 8 };
    for i in (0..count_bits).rev() {
        bits.push((data.len() >> i) & 1 == 1);
    }
    // payload bytes
    for &byte in data {
        for i in (0..8).rev() {
            bits.push((byte >> i) & 1 == 1);
        }
    }
    // terminator: up to 4 zero bits
    let term = 4.min(data_len * 8 - bits.len());
    bits.resize(bits.len() + term, false);
    // pad to byte boundary
    let byte_pad = (8 - bits.len() % 8) % 8;
    bits.resize(bits.len() + byte_pad, false);
    // pad codewords 0xEC, 0x11 alternating
    let mut out = Vec::with_capacity(data_len);
    for chunk in bits.chunks(8) {
        let mut byte = 0u8;
        for (i, &b) in chunk.iter().enumerate() {
            if b {
                byte |= 1 << (7 - i);
            }
        }
        out.push(byte);
    }
    let mut pad_toggle = true;
    while out.len() < data_len {
        out.push(if pad_toggle { 0xEC } else { 0x11 });
        pad_toggle = !pad_toggle;
    }
    out
}

/// Assemble data + ECC codewords into the final interleaved stream (with padding).
fn build_codewords_full(data: &[u8], version: u8) -> Vec<u8> {
    let padded = data_codewords(data, version);
    // Re-run the block/ECC/interleave on the padded data codewords.
    let layout = &LEVEL_M[version as usize];
    let gf = gf_tables();
    let genpoly = gf.generator(layout.ec_per_block as usize);
    let ec_len = layout.ec_per_block as usize;

    let mut blocks: Vec<Vec<u8>> = Vec::new();
    let mut idx = 0;
    for &(count, dlen) in layout.groups {
        for _ in 0..count {
            let mut block = padded[idx..idx + dlen as usize].to_vec();
            idx += dlen as usize;
            let ecc = gf.ecc(&block, &genpoly);
            block.extend_from_slice(&ecc);
            blocks.push(block);
        }
    }
    let max_data_len = blocks.iter().map(|b| b.len() - ec_len).max().unwrap_or(0);
    let mut out = Vec::with_capacity(TOTAL_CODEWORDS[version as usize]);
    for i in 0..max_data_len {
        for b in &blocks {
            let dlen = b.len() - ec_len;
            if i < dlen {
                out.push(b[i]);
            }
        }
    }
    for i in 0..ec_len {
        for b in &blocks {
            out.push(b[b.len() - ec_len + i]);
        }
    }
    out
}

// ---- Matrix construction ----

fn mask_bit(mask: u8, row: usize, col: usize) -> bool {
    let (i, j) = (row as u32, col as u32);
    match mask {
        0 => (i + j) % 2 == 0,
        1 => i % 2 == 0,
        2 => j % 3 == 0,
        3 => (i + j) % 3 == 0,
        4 => (i / 2 + j / 3) % 2 == 0,
        5 => (i * j) % 2 + (i * j) % 3 == 0,
        6 => ((i * j) % 2 + (i * j) % 3) % 2 == 0,
        7 => ((i + j) % 2 + (i * j) % 3) % 2 == 0,
        _ => unreachable!(),
    }
}

fn build_matrix(version: u8, mask: u8, codewords: &[u8]) -> Qr {
    let size = 17 + 4 * version as usize;
    let mut m = vec![false; size * size];
    let mut func = vec![false; size * size];
    let idx = |r: usize, c: usize| r * size + c;

    // Finder patterns + separators.
    for &(top, left) in &[(0i32, 0i32), (0, size as i32 - 7), (size as i32 - 7, 0)] {
        for dr in -1..=7 {
            for dc in -1..=7 {
                let (r, c) = (top + dr, left + dc);
                if r < 0 || c < 0 || r >= size as i32 || c >= size as i32 {
                    continue;
                }
                let inside = (0..7).contains(&dr) && (0..7).contains(&dc);
                let dark = inside
                    && (dr == 0
                        || dr == 6
                        || dc == 0
                        || dc == 6
                        || ((2..=4).contains(&dr) && (2..=4).contains(&dc)));
                m[idx(r as usize, c as usize)] = dark;
                func[idx(r as usize, c as usize)] = true;
            }
        }
    }

    // Timing patterns (row 6 / col 6), dark at even coordinates.
    for i in 8..size - 8 {
        let dark = i % 2 == 0;
        m[idx(6, i)] = dark;
        func[idx(6, i)] = true;
        m[idx(i, 6)] = dark;
        func[idx(i, 6)] = true;
    }

    // Alignment patterns (skip the three finder corners).
    let coords = ALIGN[version as usize];
    let size_i = size as i32;
    for &r in coords {
        for &c in coords {
            let (ri, ci) = (r as i32, c as i32);
            if (ri <= 8 && ci <= 8)
                || (ri <= 8 && ci >= size_i - 9)
                || (ri >= size_i - 9 && ci <= 8)
            {
                continue;
            }
            for dr in -2i32..=2i32 {
                for dc in -2i32..=2i32 {
                    let dark = dr.abs() == 2 || dc.abs() == 2 || (dr == 0 && dc == 0);
                    m[idx((ri + dr) as usize, (ci + dc) as usize)] = dark;
                    func[idx((ri + dr) as usize, (ci + dc) as usize)] = true;
                }
            }
        }
    }

    // Dark module + reserve format-info cells.
    let dark_mod_row = 4 * version as usize + 9;
    m[idx(dark_mod_row, 8)] = true;
    func[idx(dark_mod_row, 8)] = true;
    for i in 0..6 {
        func[idx(8, i)] = true;
        func[idx(i, 8)] = true;
    }
    func[idx(8, 7)] = true;
    func[idx(8, 8)] = true;
    func[idx(7, 8)] = true;
    for i in 0..7 {
        func[idx(size - 1 - i, 8)] = true;
    }
    for i in 0..8 {
        func[idx(8, size - 1 - i)] = true;
    }

    // Reserve version-info blocks (v7+).
    if version >= 7 {
        for i in 0..18 {
            let (r, c) = (i / 3, i % 3);
            func[idx(size - 11 + c, r)] = true;
            func[idx(r, size - 11 + c)] = true;
        }
    }

    // Data placement: zigzag from bottom-right, skipping function modules.
    let total_bits = codewords.len() * 8;
    let mut bit_idx = 0usize;
    let mut col = size - 1;
    let mut upward = true;
    while col > 0 {
        if col == 6 {
            col -= 1;
        }
        for i in 0..size {
            let row = if upward { size - 1 - i } else { i };
            for c in [col, col - 1] {
                if !func[idx(row, c)] {
                    let bit = if bit_idx < total_bits {
                        (codewords[bit_idx / 8] >> (7 - (bit_idx % 8))) & 1 == 1
                    } else {
                        false // remainder bits
                    };
                    m[idx(row, c)] = bit;
                    bit_idx += 1;
                }
            }
        }
        upward = !upward;
        col = col.wrapping_sub(2);
        if col == usize::MAX {
            break;
        }
    }

    // Apply mask to non-function modules.
    for r in 0..size {
        for c in 0..size {
            if !func[idx(r, c)] && mask_bit(mask, r, c) {
                m[idx(r, c)] = !m[idx(r, c)];
            }
        }
    }

    // Format info (15 bits, ECC level M = 00), empirically matched to the QR
    // spec: copy 1 col 8 carries bits 0-7 downward and row 8 bits 14-8 rightward;
    // copy 2 col 8 carries bits 8-14 downward and row 8 bits 7-0 rightward.
    let fmt = format_bits(mask);
    let bit = |i: usize| (fmt >> i) & 1 == 1;
    // Copy 1 (top-left): column 8 downward = bits 0..7.
    for i in 0..6 {
        m[idx(i, 8)] = bit(i);
    }
    m[idx(7, 8)] = bit(6);
    m[idx(8, 8)] = bit(7);
    // Copy 1: row 8 rightward = bits 8..14 (bit 14 at column 0).
    m[idx(8, 7)] = bit(8);
    for i in 9..15 {
        m[idx(8, 14 - i)] = bit(i);
    }
    // Copy 2 (bottom-left column): rows size-7..size-1 = bits 8..14.
    for i in 8..15 {
        m[idx(size - 15 + i, 8)] = bit(i);
    }
    // Copy 2 (top-right row): cols size-8..size-1 = bits 7..0 (bit 0 at size-1).
    for i in 0..8 {
        m[idx(8, size - 1 - i)] = bit(i);
    }
    // The dark module at (size-8, 8) was set dark during function placement.

    // Version info (v7+).
    if version >= 7 {
        let ver = version_bits(version);
        for i in 0..18 {
            let b = (ver >> i) & 1 == 1;
            m[idx(size - 11 + (i % 3), i / 3)] = b;
            m[idx(i / 3, size - 11 + (i % 3))] = b;
        }
    }

    Qr { size, modules: m }
}

/// BCH(15,5) format info for EC level M (00) + `mask`, XOR-masked with 0x5412.
fn format_bits(mask: u8) -> u16 {
    // ECC level M contributes bits 00, so the 5-bit data field is just the mask.
    let data: u16 = mask as u16;
    let mut rem: u16 = data << 10;
    for i in (10..15).rev() {
        if rem & (1 << i) != 0 {
            rem ^= 0x537 << (i - 10);
        }
    }
    ((data << 10) | (rem & 0x3ff)) ^ 0x5412
}

/// BCH(18,6) version info for `version` (v7+).
fn version_bits(version: u8) -> u32 {
    let mut rem: u32 = (version as u32) << 12;
    for i in (12..18).rev() {
        if rem & (1 << i) != 0 {
            rem ^= 0x1f25 << (i - 12);
        }
    }
    ((version as u32) << 12) | (rem & 0xfff)
}

/// Evaluate all 8 masks on a throwaway matrix and pick the lowest penalty.
fn pick_mask(version: u8, codewords: &[u8]) -> u8 {
    let mut best_mask = 0u8;
    let mut best_score = u64::MAX;
    for mask in 0..8 {
        let qr = build_matrix(version, mask, codewords);
        let score = penalty(&qr);
        if score < best_score {
            best_score = score;
            best_mask = mask;
        }
    }
    best_mask
}

/// QR mask penalty (ISO 18004 §8.8.2), lower is better.
fn penalty(qr: &Qr) -> u64 {
    let s = qr.size;
    let mut score = 0u64;
    let get = |r: usize, c: usize| qr.get(r, c);

    // Rule 1: runs of ≥5 same-colour modules in rows/cols.
    for axis in 0..2 {
        for a in 0..s {
            let mut run = 1u64;
            let mut prev = get(if axis == 0 { a } else { 0 }, if axis == 0 { 0 } else { a });
            for b in 1..s {
                let cur = get(if axis == 0 { a } else { b }, if axis == 0 { b } else { a });
                if cur == prev {
                    run += 1;
                } else {
                    if run >= 5 {
                        score += 3 + (run - 5);
                    }
                    run = 1;
                    prev = cur;
                }
            }
            if run >= 5 {
                score += 3 + (run - 5);
            }
        }
    }

    // Rule 2: 2×2 blocks of the same colour.
    for r in 0..s - 1 {
        for c in 0..s - 1 {
            let v = get(r, c);
            if v == get(r, c + 1) && v == get(r + 1, c) && v == get(r + 1, c + 1) {
                score += 3;
            }
        }
    }

    // Rule 3: finder-like patterns 1:1:3:1:1 with 4 light on one side.
    let pat_dark = [
        true, false, true, true, true, false, true, false, false, false, false,
    ];
    let pat_light = [
        false, false, false, false, true, false, true, true, true, false, true,
    ];
    let matches = |get_line: &dyn Fn(usize) -> bool, start: usize| {
        let mut d = true;
        let mut l = true;
        for k in 0..11 {
            let v = get_line(start + k);
            if v != pat_dark[k] {
                d = false;
            }
            if v != pat_light[k] {
                l = false;
            }
        }
        d || l
    };
    for r in 0..s {
        for c in 0..s {
            if c + 11 <= s {
                let line = |k: usize| get(r, c + k);
                if matches(&line, 0) {
                    score += 40;
                }
            }
            if r + 11 <= s {
                let line = |k: usize| get(r + k, c);
                if matches(&line, 0) {
                    score += 40;
                }
            }
        }
    }

    // Rule 4: deviation of dark-module proportion from 50%.
    let dark = qr.modules.iter().filter(|&&b| b).count() as u64;
    let total = (s * s) as u64;
    let percent = dark * 100 / total;
    let k = (percent as i64 - 50).unsigned_abs() / 5;
    score += k * 10;

    score
}

/// Render to terminal lines using half-block glyphs (2 modules per character
/// row) with an ANSI white background and black modules for reliable scanning.
pub fn render_terminal(qr: &Qr) -> String {
    let quiet = 4i32;
    let total = qr.size as i32 + 2 * quiet;
    let rows = (total + 1) / 2;
    let module = |r: i32, c: i32| -> bool {
        if r < 0 || c < 0 || r >= qr.size as i32 || c >= qr.size as i32 {
            false
        } else {
            qr.get(r as usize, c as usize)
        }
    };
    let mut out = String::new();
    for pr in 0..rows {
        for c in 0..total {
            let top = module(pr * 2 - quiet, c - quiet);
            let bot = module(pr * 2 + 1 - quiet, c - quiet);
            let (glyph, fg, bg) = match (top, bot) {
                (true, true) => ("█", 30, 40),
                (true, false) => ("▀", 30, 47),
                (false, true) => ("▄", 30, 47),
                (false, false) => (" ", 30, 47),
            };
            out.push_str(&format!("\x1b[{fg}m\x1b[{bg}m{glyph}"));
        }
        out.push_str("\x1b[0m\n");
    }
    out
}

#[cfg(test)]
#[path = "qr_ref_data.rs"]
mod refdata;

#[cfg(test)]
mod tests {
    use super::*;

    /// Render a QR matrix to a `\n`-separated 0/1 string for reference comparison.
    fn matrix_string(qr: &Qr) -> String {
        (0..qr.size)
            .map(|r| {
                (0..qr.size)
                    .map(|c| if qr.get(r, c) { '1' } else { '0' })
                    .collect::<String>()
            })
            .collect::<Vec<_>>()
            .join("\n")
    }

    fn check(payload: &str, version: u8, mask: u8, expected: &str) {
        let qr = encode_forced(payload.as_bytes(), version, Some(mask))
            .unwrap_or_else(|e| panic!("encode failed: {e}"));
        assert_eq!(
            matrix_string(&qr),
            expected,
            "matrix mismatch for v{version} mask{mask}"
        );
    }

    #[test]
    fn matches_reference_short_v3_m0() {
        check("CHERNOBYL", 3, 0, refdata::REF_SHORT_V3_M0);
    }

    #[test]
    fn matches_reference_align_v5_m2() {
        check("CHERNOBYL", 5, 2, refdata::REF_ALIGN_V5_M2);
    }

    #[test]
    fn matches_reference_payload_v9_m0() {
        check(refdata::BIG_PAYLOAD, 9, 0, refdata::REF_PAYLOAD_V9_M0);
    }

    #[test]
    fn matches_reference_payload_v9_m3() {
        check(refdata::BIG_PAYLOAD, 9, 3, refdata::REF_PAYLOAD_V9_M3);
    }

    #[test]
    fn format_and_version_bits_match_spec() {
        // Known QR format strings (EC level M).
        assert_eq!(format_bits(0), 0x5412);
        assert_eq!(format_bits(1), 0x5125);
        // Known version info for v7.
        assert_eq!(version_bits(7), 0x07c94);
    }

    #[test]
    fn byte_capacity_matches_standard_table() {
        assert_eq!(byte_capacity(1), 14);
        assert_eq!(byte_capacity(2), 26);
        assert_eq!(byte_capacity(9), 180);
        assert_eq!(byte_capacity(10), 213);
        assert_eq!(byte_capacity(11), 251);
        assert_eq!(byte_capacity(13), 331);
        assert_eq!(byte_capacity(15), 412);
    }

    #[test]
    fn auto_version_picks_smallest_fit() {
        // 160-byte payload needs v9 in byte mode (v8 caps at 152).
        let payload = refdata::BIG_PAYLOAD.as_bytes();
        assert_eq!(payload.len(), 160);
        let qr = encode(payload).expect("160 bytes must fit some version");
        assert_eq!(qr.size, 53, "160 bytes byte-mode should select v9 (53×53)");
    }

    #[test]
    fn matches_reference_tunnel_pairing_v11_m1() {
        // LAN + ngrok endpoints: the payload that outgrew v10
        check(
            refdata::REF_TUNNEL_V11_M1_PAYLOAD,
            11,
            1,
            refdata::REF_TUNNEL_V11_M1,
        );
        let auto = encode(refdata::REF_TUNNEL_V11_M1_PAYLOAD.as_bytes()).unwrap();
        assert_eq!(auto.size, 61, "247 bytes should select v11");
    }

    #[test]
    fn matches_reference_v14_m4_and_v15_m6() {
        // v14+: four alignment rows and 3 remainder bits
        check(
            refdata::REF_PAYLOAD_V14_M4_PAYLOAD,
            14,
            4,
            refdata::REF_PAYLOAD_V14_M4,
        );
        check(
            refdata::REF_PAYLOAD_V15_M6_PAYLOAD,
            15,
            6,
            refdata::REF_PAYLOAD_V15_M6,
        );
    }

    #[test]
    fn rejects_oversized_payload() {
        let big = vec![b'a'; 413];
        assert!(encode(&big).is_err());
    }

    #[test]
    fn round_trip_codeword_stream_is_stable() {
        // The same payload must always produce identical codewords.
        let a = build_codewords_full(b"CHERNOBYL", 5);
        let b = build_codewords_full(b"CHERNOBYL", 5);
        assert_eq!(a, b);
        assert!(!a.is_empty());
    }

    #[test]
    fn terminal_render_has_expected_dimensions() {
        let qr = encode(b"CHERNOBYL").unwrap();
        let rendered = render_terminal(&qr);
        let lines: Vec<&str> = rendered.lines().collect();
        let width = qr.size + 8; // quiet zone 4 each side
        assert_eq!(lines.len(), width.div_ceil(2));
        assert!(lines[0].starts_with("\x1b["));
        assert!(
            lines[0].contains('\u{2588}')
                || lines[0].contains('\u{2580}')
                || lines[0].contains(' ')
        );
    }
}
